Ext._define('judicial.ScientifyWorkplaceGrid', {
    extend: 'core.RestfulGrid',

    restWindow: 'judicial.ScientifyWorkplaceWindow',

    configOrderToolBar: ['add', 'edit', 'remove', '-', 'singleDispatch', '-', 'search', '->', 'download'],

    getSingleDispatchAction: function(cfg) {
        if(!this._singleDispatchAction)
            this._singleDispatchAction = Ext._create('Ext.Button', {
                text: 'Enviar',
                iconCls: 'icon-judicial icon-ejud-triage-effectivate',
                scope: this,
                handler: this.dispatchSingle
            });

        return this._singleDispatchAction;
    },

    dispatchSingle: function() {
        var selection = this.getSelectionModel().getSelections();

        if(selection.length > 0)
            Ext.Msg.show({
                title: 'Despachando comunicações',
                msg: 'Tem certeza que deseja despachar as comunicações pendentes?',
                icon: Ext.Msg.QUESTION,
                buttons: Ext.Msg.YESNO,
                scope: this,
                fn: function(btn) {
                    if(btn === 'no') return;
                    var mask = new Ext.LoadMask(this.getEl(), {msg: 'dispachando...'});

                    mask.show();
                    this.factoryRestful().dispatch(
                        selection.map(function(data) { return data.get('pk'); }),
                        {
                            scope: this,
                            fn: function(rst) {
                                this.getStore().reload();
                            }
                        },
                        false,
                        {
                            fn: function() { mask.hide(); }
                        }
                    );
                }
            });
        else
            Ext.Msg.show({
                title: 'Despachando comunicações',
                msg: 'Nenhuma comunicação pendente foi selecionada para despachar.',
                icon: Ext.Msg.ERROR,
                buttons: Ext.Msg.OK
            });
    },

    getColumnModel: function() {
        if(!this._columnModel)
            this._columnModel = Ext._create(
                'Ext.grid.ColumnModel',
                [
                    Ext._create('Ext.grid.RowNumberer'),
                    {header: 'Local', dataIndex: 'location_unicode', id: 'autoExpandColumn'},
                    {header: 'Origem', dataIndex: 'part_unicode', width: 120, hidden: true},
                    {header: 'Protocolo', dataIndex: 'protocol_code', width: 120},
                    {header: 'Recebido', dataIndex: 'received_by_unicode', width: 180},
                    {header: 'Data', dataIndex: 'received_at', width: 105, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i')},
                    {header: 'Criado', dataIndex: 'created_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true},
                    {header: 'Data', dataIndex: 'created_by_unicode', width: 120, hidden: true},
                    {header: 'Modificado', dataIndex: 'modified_by_unicode', width: 120, hidden: true},
                    {header: 'Data', dataIndex: 'modified_at', width: 90, renderer: Ext.util.Format.dateRenderer('d/m/Y H:i'), hidden: true}
                ]
            );

        return this._columnModel;
    }
});

core.RestfulGrid.register(
    'judicial.ScientifyWorkplaceRestful',
    'judicial.ScientifyWorkplaceGrid'
);
